 if((net.settings.qualityMode||'none')==='chemical'&&net.settings.qualitySourceNode&&!net.nodes.some(n=>n.id===net.settings.qualitySourceNode))e.push('The water-quality source node does not exist in this network.');
 if((net.settings.qualityMode||'none')!=='none'&&(!(net.settings.qualityStepMinutes||5)||(net.settings.qualityStepMinutes||5)<=0))e.push('Water-quality timestep must be greater than zero.');if((net.settings.qualityMode||'none')!=='none'&&!(net.settings.duration>0))e.push('Set a positive simulation duration to run water-quality analysis; a zero-hour run cannot assess water movement over time.');
