 const sharedPattern=String(net.settings.demandPattern||'').trim();const activePatterns=[...net.nodes.filter(n=>n.kind==='J'&&String(n.demandPattern||'').trim()).map(n=>({id:n.id,value:String(n.demandPattern||'').trim()})),...(sharedPattern?[{id:'shared fallback',value:sharedPattern}]:[])];if(activePatterns.length){if(!(net.settings.duration>0))e.push('Demand patterns require a positive extended-period simulation duration.');if(!(net.settings.patternStep>0))e.push('Demand pattern timestep must be positive.');activePatterns.forEach(p=>{const values=p.value.split(/[\s,]+/).filter(Boolean).map(Number);if(!values.length||values.some(v=>!Number.isFinite(v)||v<0))e.push(p.id+': demand pattern must contain comma- or space-separated non-negative numeric multipliers.');});}if(!Number.isFinite(net.settings.pumpEfficiency??75)||(net.settings.pumpEfficiency??75)<=0||(net.settings.pumpEfficiency??75)>100)e.push('Pump efficiency must be greater than 0 and no more than 100%.');if(!Number.isFinite(net.settings.energyTariff??30)||(net.settings.energyTariff??30)<0)e.push('Energy tariff cannot be negative.');if(!Number.isFinite(net.settings.operatingHoursPerDay??12)||(net.settings.operatingHoursPerDay??12)<0||(net.settings.operatingHoursPerDay??12)>24)e.push('Pump operating hours per day must be between 0 and 24.');
