 (net.settings.tankControls||[]).forEach((c,i)=>{const pump=net.links.find(l=>l.id===c.linkId),tank=net.nodes.find(n=>n.id===c.tankId);if(!pump||pump.kind!=='pump')e.push('Tank control '+(i+1)+': select an existing pump link.');if(!tank||tank.kind!=='T')e.push('Tank control '+(i+1)+': select an existing storage tank.');if(!['OPEN','CLOSED'].includes(c.status))e.push('Tank control '+(i+1)+': action must be OPEN or CLOSED.');if(!['ABOVE','BELOW'].includes(c.condition)||!Number.isFinite(c.level))e.push('Tank control '+(i+1)+': enter a valid tank level and ABOVE/BELOW condition.');});
