function diagnose(net:Net,nodes:NR[],links:LR[]){
 const s:string[]=[];
 nodes.filter(n=>n.minPressure<net.settings.minPressure).forEach(n=>s.push(n.id+': minimum pressure '+n.minPressure.toFixed(2)+' m is below the '+net.settings.minPressure+' m criterion. Review source hydraulic grade, node elevation, peak demand and cumulative upstream headloss. Test larger/parallel mains or a correctly selected booster pump as separate scenarios; verify pump duty and pipe pressure class before adopting changes.'));
 nodes.filter(n=>n.maxPressure>net.settings.maxPressure).forEach(n=>s.push(n.id+': maximum pressure '+n.maxPressure.toFixed(2)+' m exceeds the '+net.settings.maxPressure+' m criterion. Review static head, terrain profile and pressure zoning; assess a PRV or break-pressure tank after checking transient conditions.'));
 links.filter(l=>l.kind==='pipe'&&l.maxVelocity>net.settings.maxVelocity).forEach(l=>s.push(l.id+': maximum simulated velocity '+l.maxVelocity.toFixed(2)+' m/s exceeds the '+net.settings.maxVelocity+' m/s limit. Recheck peak flow and internal diameter; compare larger diameter or parallel pipeline options and rerun headloss and cost calculations.'));
 links.filter(l=>l.kind==='pipe'&&l.minVelocity<net.settings.minVelocity).forEach(l=>s.push(l.id+': minimum simulated velocity '+l.minVelocity.toFixed(2)+' m/s is below the '+net.settings.minVelocity+' m/s minimum. Review current/future demand, water age and flushing needs before changing diameter.'));
 links.filter(l=>l.kind==='pump'&&l.status!=='Open').forEach(l=>s.push(l.id+': pump is not in a normal open state. Review pump curve, system head, direction and duty point.'));
 if(links.length&&links.every(l=>Math.abs(l.flow)<1e-8)){
   const positiveDemand=net.nodes.some(n=>n.kind==='J'&&n.demand>1e-9);
   s.unshift(positiveDemand
    ? 'ZERO-FLOW CHECK: Every link is reporting approximately 0 flow. Confirm that the source reservoir head is the actual water-surface hydraulic elevation (not ground elevation), all supply links are open, the source is connected through the intended route, and no closed valve or incorrectly directed pump isolates the demand nodes.'
    : 'ZERO-FLOW CHECK: Every link is reporting approximately 0 flow and no junction has a positive demand. Enter the actual design demand (L/s) at the GIS Junction features, then save and reopen the network in EPANET. A pipe drawing by itself does not create water demand or flow.');
  }
  if(!s.length)s.push('No pressure or pipe-velocity exceedances were detected against the selected criteria. Also review peak-hour/fire-flow cases, transient pressure, source reliability, water age and applicable design standards.');
 return s;
}

