   const preferred=String(p.epanetId||'');const id=preferred&&idOk(preferred)&&!used.has(preferred)?(used.add(preferred),preferred):safeId(kind==='J'?'GJ':kind==='R'?'GR':'GT',String(f.id||p.name||nodeRows.length+1));nodeRows.push({feature:f,kind,coord:[Number(c[0]),Number(c[1])],id});
