  const nodeByReference=new Map<string,any>();nodeRows.forEach(row=>{nodeByReference.set(row.id,row);nodeByReference.set(String(row.feature.id||''),row);nodeByReference.set(String(row.feature.properties?.epanetId||''),row)});
  const nodes:N[]=nodeRows.map(row=>{const p=row.feature.properties;return {id:row.id,kind:row.kind,x:0,y:0,elevation:validNumber(p.elevation_m)?Number(p.elevation_m):0,demand:row.kind==='J'&&validNumber(p.demand_lps)?Number(p.demand_lps):0,head:row.kind==='R'&&validNumber(p.reservoir_head_m)?Number(p.reservoir_head_m):0,initialLevel:row.kind==='T'&&validNumber(p.tank_initial_level_m)?Number(p.tank_initial_level_m):0,minLevel:row.kind==='T'&&validNumber(p.tank_min_level_m)?Number(p.tank_min_level_m):0,maxLevel:row.kind==='T'&&validNumber(p.tank_max_level_m)?Number(p.tank_max_level_m):0,diameter:row.kind==='T'&&validNumber(p.tank_diameter_m)?Number(p.tank_diameter_m):0,minVolume:row.kind==='T'&&validNumber(p.tank_min_volume_m3)?Number(p.tank_min_volume_m3):0,volumeCurve:row.kind==='T'?String(p.tank_volume_curve||'')||undefined:undefined}});
  const xs=nodeRows.map(n=>n.coord[0]),ys=nodeRows.map(n=>n.coord[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);nodes.forEach((n,i)=>{n.x=50+(maxX===minX?0.5:(nodeRows[i].coord[0]-minX)/(maxX-minX))*800;n.y=40+(maxY===minY?0.5:(1-(nodeRows[i].coord[1]-minY)/(maxY-minY)))*340});
