   const start=coords[0],end=coords[coords.length-1];const nearest=(c:number[])=>nodeRows.map(n=>({n,d:haversine(c,n.coord)})).sort((a,b)=>a.d-b.d)[0];const fromRef=String(p.from_node_id||''),toRef=String(p.to_node_id||'');const explicitA=fromRef?nodeByReference.get(fromRef):null,explicitB=toRef?nodeByReference.get(toRef):null;const nearA=nearest(start),nearB=nearest(end);const a=fromRef?{n:explicitA,d:explicitA?haversine(start,explicitA.coord):Infinity}:nearA;const b=toRef?{n:explicitB,d:explicitB?haversine(end,explicitB.coord):Infinity}:nearB;if(!a?.n||!b?.n){issues.push((p.name||f.id||'Pipeline')+': upstream/downstream node reference does not match a hydraulic GIS point. Re-select both endpoint nodes.');return}if(a.d>75||b.d>75){issues.push((p.name||f.id||'Pipeline')+': line endpoints must be within 75 m of the selected hydraulic nodes. Correct the node references or move the line vertices; endpoint offsets are '+a.d.toFixed(1)+' m and '+b.d.toFixed(1)+' m.');return}if(a.n.id===b.n.id){issues.push((p.name||f.id||'Pipeline')+': both line ends resolve to the same node. Connect two different hydraulic nodes.');return}
   let length=0;for(let j=1;j<coords.length;j++)length+=haversine(coords[j-1],coords[j]);if(validNumber(p.length_m)&&Number(p.length_m)>0)length=Number(p.length_m);
   const preferred=String(p.epanetId||'');const linkId=preferred&&idOk(preferred)&&!used.has(preferred)?(used.add(preferred),preferred):safeId(kind==='pump'?'GPU':kind==='valve'?'GV':'GP',String(f.id||p.name||i+1));
   const suppliedPumpCurve=String(p.pump_curve||'').trim()||(validNumber(p.pump_flow_lps)&&validNumber(p.pump_head_m)?String(p.pump_flow_lps)+':'+String(p.pump_head_m):'');const suppliedValveCurve=String(p.valve_curve||p.pump_curve||'').trim();
   links.push({id:linkId,kind,from:a.n.id,to:b.n.id,length:kind==='pipe'?length:0,pumpPower:kind==='pump'&&validNumber(p.pump_power_hp)?Number(p.pump_power_hp):undefined,diameter:kind==='pump'?0:(Number.isFinite(diameter)&&diameter>0?diameter:0),roughness:kind==='pipe'?(Number.isFinite(roughness)&&roughness>0?roughness:0):130,status:p.link_status==='Closed'?'Closed':p.link_status==='CV'?'CV':'Open',minorLoss:Number(p.minor_loss_k||0),valveType:(p.valve_type||'PRV') as L['valveType'],setting:Number(p.valve_setting||30),pumpCurve:kind==='pump'?suppliedPumpCurve:kind==='valve'&&String(p.valve_type||'').toUpperCase()==='GPV'?suppliedValveCurve:'20:10'});
